  init() {
    this.render();
    this.attachEventListeners();
  }

  render() {
    const container = document.getElementById('app');
    container.innerHTML = this.renderQuizTemplate();
  }

  renderQuizTemplate() {
    return `
      <div class="quiz-container">
        ${this.renderHeader()}
        <form id="quizForm">
          ${quizData.map(question => this.renderQuestion(question)).join('')}
          ${this.renderButtons()}
          ${this.renderFeedback()}
        </form>
      </div>
    `;
  }

  renderHeader() {
    return `
      <div class="quiz-header">
        <h1>Programming Languages Quiz</h1>
        <p>Test your knowledge about computer programming languages</p>
      </div>
    `;
  }

  renderQuestion(question) {
    const hasHelp = question.helpText;
    return `
      <div class="form-field">
        <h2>
          <span class="question-number">${question.number}</span>
          ${this.escapeHtml(question.question)}
        </h2>
        ${hasHelp ? `<div class="help-text">${this.escapeHtml(hasHelp)}</div>` : ''}
        <div class="options-group">
          ${question.options.map(option => this.renderOption(question.id, option)).join('')}
        </div>
      </div>
    `;
  }

  renderOption(questionId, option) {
    const isChecked = this.state.answers[option.id] ? 'checked' : '';
    return `
      <div class="checkbox-wrapper">
        <input
          type="checkbox"
          id="${option.id}"
          name="${questionId}"
          value="${option.id}"
          data-correct="${option.correct}"
          ${isChecked}
        />
        <label for="${option.id}">${this.escapeHtml(option.label)}</label>
      </div>
    `;
  }

  renderButtons() {
    return `
      <div class="button-group">
        <button type="submit" class="submit-btn">Submit Quiz</button>
        <button type="reset" class="reset-btn">Clear Answers</button>
      </div>
    `;
  }

  renderFeedback() {
    return `<div id="feedback" class="feedback"></div>`;
  }

  attachEventListeners() {
    const form = document.getElementById('quizForm');
    const checkboxes = form.querySelectorAll('input[type="checkbox"]');

    checkboxes.forEach(checkbox => {
      checkbox.addEventListener('change', () => this.handleCheckboxChange(checkbox));
    });

    form.addEventListener('submit', (e) => this.handleSubmit(e));
    form.addEventListener('reset', () => this.handleReset());
  }

  handleCheckboxChange(checkbox) {
    if (checkbox.checked) {
      this.state.answers[checkbox.id] = true;
    } else {
      delete this.state.answers[checkbox.id];
    }
  }

  handleSubmit(e) {
    e.preventDefault();
