  handleReset() {
    this.state.answers = {};
    const feedback = document.getElementById('feedback');
    feedback.classList.remove('show', 'success', 'error');
  }

  calculateScore() {
    let correct = 0;
    let total = 0;

    quizData.forEach(question => {
      const selectedOptions = question.options.filter(
        option => this.state.answers[option.id]
      );
      const correctOptions = question.options.filter(option => option.correct);

      const isCorrect =
        selectedOptions.length === correctOptions.length &&
        selectedOptions.every(opt => opt.correct);

      if (isCorrect) {
        correct++;
      }
      total++;
    });

    return { correct, total };
  }

  showFeedback(result) {
    const feedback = document.getElementById('feedback');
    const percentage = Math.round((result.correct / result.total) * 100);
    const isSuccess = result.correct === result.total;

    let message = `You got ${result.correct} out of ${result.total} questions correct (${percentage}%).`;

    if (isSuccess) {
      message += ' 🎉 Perfect score!';
      feedback.className = 'feedback show success';
    } else if (result.correct >= result.total / 2) {
      message += ' Good effort! Review the questions you missed.';
      feedback.className = 'feedback show success';
    } else {
      message += ' Keep learning! Try reviewing the material.';
      feedback.className = 'feedback show error';
    }

    feedback.textContent = message;
  }

  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }
}

